/// <summary>
/// Extension of table MarkupTransHistory
/// </summary>
[ExtensionOf(tableStr(MarkupTransHistory))]
final class AVAMarkupTransHistoryDbt_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the history record based on a <c>MarkupTrans</c> record.
/// </summary>
/// <param name="_markupTrans">
/// The <c>MarkupTrans</c> record to use for initialization.
/// </param>
public void initFromMarkupTrans(MarkupTrans _markupTrans)
{
    next initFromMarkupTrans(_markupTrans);

    this.AVACalcQty = _markupTrans.AVACalcQty;
}

/// <summary>
/// extension of insert method
/// </summary>
public void insert()
{
    if(!this.AVACalcQty)
    {
        this.AVACalcQty = MarkupTrans::avaFindMarkupTrans(this.TransTableId, this.TransRecId, this.LineNum).AVACalcQty;
    }

    next insert();
}
